public static async Task<IReadOnlyList<(int BlogId, int TotalViews)>> GetViewsByBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogPosts
        select (BlogId: blogPosts.Key, TotalViews: blogPosts.Sum(post => post.Views));

    return await query.ToListAsync(cancellationToken);
}
