```csharp
public static async Task<Dictionary<int, int>> GetViewsByBlogIdAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId
        into blogPosts
        select new
        {
            BlogId = blogPosts.Key,
            TotalViews = blogPosts.Sum(post => post.Views)
        };

    var results = await query.ToListAsync(cancellationToken);

    return results.ToDictionary(result => result.BlogId, result => result.TotalViews);
}
```

